// md-exfil T12: every route that returns stored or generated bytes sends the artifact headers. The collaborators are fakes.
//
//   node --test server/routes/artifactHeaders.routes.test.ts
import test from 'node:test'
import assert from 'node:assert/strict'
import express from 'express'
import type { Express, NextFunction, Request, Response } from 'express'
import type { AddressInfo } from 'node:net'

import registerImageRoutes from './images.ts'
import registerDeckRoutes from './decks.ts'
import registerDocumentRoutes from './documents.ts'
import registerSpreadsheetRoutes from './spreadsheets.ts'

const CSP = "default-src 'none'; img-src 'self' data:; style-src 'unsafe-inline'; sandbox"
const auth = (req: Request, _res: Response, next: NextFunction) => (Object.assign(req, { email: 'a@example.com', token: 'tok' }), next())
const SVG = Buffer.from('<svg xmlns="http://www.w3.org/2000/svg"><script>window.pwned=1</script></svg>')
const PNG = Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==', 'base64')

async function serve(register: (app: Express, deps: never) => void, deps: Record<string, unknown>) {
  const app = express()
  app.use(express.json())
  register(app, { auth, ensureReady: async () => {}, ...deps } as never)
  const server = await new Promise<import('node:http').Server>((r) => { const s = app.listen(0, '127.0.0.1', () => r(s)) })
  const base = `http://127.0.0.1:${(server.address() as AddressInfo).port}`
  return { get: (p: string) => fetch(base + p), post: (p: string, body: unknown) => fetch(base + p, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(body) }), close: () => server.close() }
}
const image = (contentType: string | null, bytes: Buffer) => ({ getImage: async () => ({ id: '7', contentType, volumePath: '/v/7', shared: false, readOnly: false }), getImageBytes: async () => bytes })

test('GET /api/images/:id as SVG: attachment, the policy, nosniff, the right type', async () => {
  const s = await serve(registerImageRoutes, image('image/svg+xml', SVG))
  try {
    const r = await s.get('/api/images/7')
    assert.equal(r.status, 200)
    assert.equal(r.headers.get('content-type'), 'image/svg+xml')
    assert.match(r.headers.get('content-disposition') || '', /^attachment; filename="image-7\.svg"$/)
    assert.equal(r.headers.get('content-security-policy'), CSP)
    assert.equal(r.headers.get('x-content-type-options'), 'nosniff')
    assert.deepEqual(Buffer.from(await r.arrayBuffer()), SVG)
  } finally { s.close() }
})

test('GET /api/images/:id as HTML (a hostile stored type): attachment too', async () => {
  const s = await serve(registerImageRoutes, image('text/html', Buffer.from('<script>1</script>')))
  try {
    const r = await s.get('/api/images/7')
    assert.match(r.headers.get('content-disposition') || '', /^attachment/)
    assert.equal(r.headers.get('content-security-policy'), CSP)
  } finally { s.close() }
})

test('GET /api/images/:id as PNG: inline (for <img>), still with the policy and nosniff', async () => {
  const s = await serve(registerImageRoutes, image('image/png', PNG))
  try {
    const r = await s.get('/api/images/7')
    assert.equal(r.headers.get('content-type'), 'image/png')
    assert.equal(r.headers.get('content-disposition'), null)
    assert.equal(r.headers.get('content-security-policy'), CSP)
    assert.equal(r.headers.get('x-content-type-options'), 'nosniff')
  } finally { s.close() }
})

test('GET /api/images/:id with no stored type defaults to image/png inline', async () => {
  const s = await serve(registerImageRoutes, image(null, PNG))
  try {
    const r = await s.get('/api/images/7')
    assert.equal(r.headers.get('content-type'), 'image/png')
    assert.equal(r.headers.get('content-disposition'), null)
  } finally { s.close() }
})

test('a shared image answering 304 is not a second path: the 200 carries the headers', async () => {
  const s = await serve(registerImageRoutes, { getImage: async () => ({ id: '7', contentType: 'image/svg+xml', volumePath: '/v/7', shared: true, readOnly: false }), getImageBytes: async () => SVG })
  try {
    const r = await s.get('/api/images/7')
    assert.match(r.headers.get('content-disposition') || '', /^attachment/)
    assert.equal(r.headers.get('content-security-policy'), CSP)
  } finally { s.close() }
})

test('the .pptx export still downloads with its name, now under the policy', async () => {
  const s = await serve(registerDeckRoutes, { getDeck: async () => ({ id: '3', title: 'Meu Deck!', slides: [] }), getSelectedDeckTemplate: async () => null, renderPptxFromOps: async () => Buffer.from('PK') })
  try {
    const r = await s.post('/api/decks/3/export-html', { slides: [{}] })
    assert.equal(r.status, 200)
    assert.equal(r.headers.get('content-type'), 'application/vnd.openxmlformats-officedocument.presentationml.presentation')
    assert.equal(r.headers.get('content-disposition'), 'attachment; filename="Meu_Deck_.pptx"')
    assert.equal(r.headers.get('content-security-policy'), CSP)
    assert.equal(r.headers.get('x-content-type-options'), 'nosniff')
  } finally { s.close() }
})

test('the .docx and .md exports still download with their names, now under the policy', async () => {
  const s = await serve(registerDocumentRoutes, { getDocument: async () => ({ id: '6', title: 'Relatório', markdown: '# R' }) })
  try {
    const docx = await s.get('/api/documents/6/export')
    assert.equal(docx.status, 200)
    assert.equal(docx.headers.get('content-type'), 'application/vnd.openxmlformats-officedocument.wordprocessingml.document')
    assert.equal(docx.headers.get('content-disposition'), 'attachment; filename="Relat_rio.docx"')
    assert.equal(docx.headers.get('content-security-policy'), CSP)
    assert.equal(docx.headers.get('x-content-type-options'), 'nosniff')
    const md = await s.get('/api/documents/6/export?format=md')
    assert.equal(md.headers.get('content-type'), 'text/markdown; charset=utf-8')
    assert.equal(md.headers.get('content-disposition'), 'attachment; filename="Relat_rio.md"')
    assert.equal(md.headers.get('content-security-policy'), CSP)
    assert.equal(md.headers.get('x-content-type-options'), 'nosniff')
  } finally { s.close() }
})

test('the .xlsx export still downloads with its name, now under the policy', async () => {
  const s = await serve(registerSpreadsheetRoutes, { getSpreadsheet: async () => ({ id: '5', title: 'Plan 1', sheets: [{ name: 'A', blocks: [{ kind: 'note', text: 'hi' }] }] }), getSelectedDeckTemplate: async () => null })
  try {
    const r = await s.get('/api/spreadsheets/5/export')
    assert.equal(r.status, 200)
    assert.equal(r.headers.get('content-type'), 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')
    assert.equal(r.headers.get('content-disposition'), 'attachment; filename="Plan_1.xlsx"')
    assert.equal(r.headers.get('content-security-policy'), CSP)
    assert.equal(r.headers.get('x-content-type-options'), 'nosniff')
  } finally { s.close() }
})
